function updateCardCycleFields(form,resetValues=true){const type=form.elements.ruleType.value,startLabel=form.elements.start.closest('label').querySelector('.label'),endLabel=form.elements.end.closest('label').querySelector('.label'),calendarDays=type==='previous-current'||type==='monthly-range';startLabel.textContent=type==='previous-current'?'전월 시작일':type==='monthly-range'?'시작일':'시작 offset';endLabel.textContent=type==='previous-current'?'당월 종료일':type==='monthly-range'?'종료일':'종료 offset';for(const field of[form.elements.start,form.elements.end]){field.min=calendarDays?'1':'-90';field.max=calendarDays?'31':'0';}if(resetValues){form.elements.start.value=calendarDays?'15':'-44';form.elements.end.value=calendarDays?'14':'-15';}}
