function showImportPreview(preview,{kind,cursor,metaPatch}={}){
  const dialog=document.createElement('dialog'),cards=state().cards.filter(card=>card.active),isExport=kind==='notion-export',limit=isExport?100:preview.newTransactions.length,visible=preview.newTransactions.slice(0,limit),aliases=preview.unmatchedCardAliases||[];
  const source=isExport?`<p class="notice"><strong>${esc(preview.csvName)}</strong><br>${preview.rowCount}행을 읽었습니다.${preview.fileName!==preview.csvName?` · ZIP: ${esc(preview.fileName)}`:''}</p>`:'';
  const categoryNotice=isExport&&preview.newCategories?.length?`<p class="hint">새 카테고리 ${preview.newCategories.map(category=>esc(category.name)).join(', ')}도 선택한 거래와 함께 추가합니다.</p>`:'';
  const cardMapping=isExport&&aliases.length?`<section class="import-mapping"><h3>카드 이름 연결</h3><p class="hint">등록된 카드와 연결하거나, 결제주기를 모르면 미연결 상태로 보존할 수 있어요.</p>${aliases.map((alias,i)=>`<label class="field"><span class="label">${esc(alias)}</span><select name="alias-${i}"><option value="">카드 미연결로 가져오기</option>${cards.map(card=>`<option value="${card.id}">${esc(card.name)}</option>`).join('')}</select></label>`).join('')}</section>`:'';
  dialog.innerHTML=`<div class="dialog-head"><h2>가져올 내용 확인</h2><button class="quiet icon-button" data-close aria-label="닫기">${icon('close')}</button></div><div class="dialog-body">${source}<div class="metric-row"><div class="metric"><span>신규</span><strong>${preview.newTransactions.length}</strong></div><div class="metric"><span>중복 후보 · 오류</span><strong>${preview.duplicates.length} · ${preview.errors.length}</strong></div></div><p class="hint">중복 후보는 자동 등록하지 않습니다. 오류가 있어도 신규 항목만 선택해 적용할 수 있어요.</p>${categoryNotice}<form id="preview-form">${cardMapping}${visible.map((tx,i)=>`<div class="import-row"><div class="row"><div><strong>${esc(tx.merchant)}</strong><p class="row-meta">사용 ${tx.date}${tx.billingDate?` · 결제 ${tx.billingDate}`:''} · ${won(tx.amount)}${tx.cardAlias?` · ${esc(tx.cardAlias)}`:''}</p></div><input type="checkbox" name="pick" value="${i}" checked aria-label="${esc(tx.merchant)} 가져오기" style="width:22px;min-height:22px"></div>${!isExport&&tx.paymentMethod==='card'&&!tx.cardId?`<label class="field"><span class="label">카드 선택</span><select name="card-${i}" required><option value="">선택하세요</option>${cards.map(card=>`<option value="${card.id}">${esc(card.name)}</option>`).join('')}</select></label>`:''}</div>`).join('')}${preview.newTransactions.length>limit?`<p class="notice">처음 ${limit}건만 미리 표시합니다. 표시하지 않은 ${preview.newTransactions.length-limit}건도 기본 선택되어 함께 적용됩니다.</p>`:''}${preview.duplicates.length?`<details><summary>중복 후보 ${preview.duplicates.length}건</summary>${preview.duplicates.slice(0,100).map(value=>`<p class="hint">${esc(value.transaction.merchant)} · ${won(value.transaction.amount)}</p>`).join('')}${preview.duplicates.length>100?`<p class="hint">외 ${preview.duplicates.length-100}건</p>`:''}</details>`:''}${preview.errors.length?`<details><summary>오류 ${preview.errors.length}건</summary>${preview.errors.slice(0,100).map(value=>`<p class="error">${esc(value.error)}</p>`).join('')}${preview.errors.length>100?`<p class="hint">외 ${preview.errors.length-100}건</p>`:''}</details>`:''}<button class="primary wide" type="submit" ${preview.newTransactions.length?'':'disabled'}>선택한 신규 내역 적용</button></form></div>`;
  document.body.append(dialog);dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();
  dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();const fd=new FormData(event.currentTarget),picked=fd.getAll('pick').map(Number);if(isExport)for(let i=limit;i<preview.newTransactions.length;i++)picked.push(i);try{const transactions=picked.map(i=>{const tx=structuredClone(preview.newTransactions[i]);if(isExport&&tx.paymentMethod==='card'&&!tx.cardId){const aliasIndex=aliases.indexOf(tx.cardAlias);tx.cardId=aliasIndex>=0?fd.get(`alias-${aliasIndex}`)||null:null;}else if(!tx.cardId&&tx.paymentMethod==='card')tx.cardId=fd.get(`card-${i}`)||null;if(!isExport&&tx.paymentMethod==='card'&&!tx.cardId)throw new Error('연결할 카드를 선택해 주세요.');return tx;}),categoryIds=new Set(transactions.map(tx=>tx.categoryId)),categories=(preview.newCategories||[]).filter(category=>categoryIds.has(category.id));await repo.applyImport({transactions,categories,importRecord:{id:uid('import'),kind,sourceFile:isExport?preview.fileName:null,csvFile:isExport?preview.csvName:null,createdAt:new Date().toISOString(),count:transactions.length,duplicateCount:preview.duplicates.length,errorCount:preview.errors.length},settingsPatch:cursor?{notificationCursor:cursor}:null,metaPatch});dialog.close();toast(`${transactions.length}건을 안전하게 적용했어요.`);render();}catch(error){toast(error.message);}};
  dialog.showModal();
}
