function registerWebMCP(){const context=document.modelContext;if(!context?.registerTool)return;const report=error=>console.warn('WebMCP tool registration failed',error);try{void Promise.resolve(context.registerTool({name:'read_budget_summary',title:'가계부 요약 읽기',description:'지정한 월의 지출, 예산, 남은 금액을 로컬 가계부에서 읽습니다.',inputSchema:{type:'object',properties:{month:{type:'string',pattern:'^\\d{4}-\\d{2}$'}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:input=>{const month=input?.month||zonedDate(new Date(),state().settings.timeZone).slice(0,7),summary=summarize(state().transactions,{month,categories:state().categories}),budget=budgetProgress(state(),month);return{month,expense:summary.expense,budget:budget.total,remaining:budget.remaining};}})).catch(report);void Promise.resolve(context.registerTool({name:'create_budget_transaction',title:'가계부 거래 추가',description:'검증된 지출 또는 이체 한 건을 같은 local-first 저장소에 추가하고 화면을 갱신합니다.',inputSchema:{type:'object',properties:{date:{type:'string',pattern:'^\\d{4}-\\d{2}-\\d{2}$'},time:{type:'string',pattern:'^([01]\\d|2[0-3]):[0-5]\\d$'},type:{type:'string',enum:['expense','transfer']},amount:{type:'number',exclusiveMinimum:0},merchant:{type:'string',minLength:1,maxLength:80},categoryId:{type:'string'},paymentMethod:{type:'string'},cardId:{type:['string','null']},memo:{type:'string',maxLength:300},installmentMonths:{type:'integer',minimum:1,maximum:36}},required:['date','time','type','amount','merchant'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){const tx=await repo.addTransaction({date:input.date,time:input.time,type:input.type,amount:input.amount,merchant:input.merchant,categoryId:input.categoryId||'other',paymentMethod:input.cardId?'card':input.paymentMethod||'cash',cardId:input.cardId||null,source:'manual',sourceId:'',memo:input.memo||'',installment:input.installmentMonths>1?{months:input.installmentMonths}:null,cancelled:false,linkedOriginal:null});view.tab='home';render();return{id:tx.id,status:'saved',revision:state().revision};}})).catch(report);}catch(error){report(error);}}
async function boot(){try{await repo.init();clearTimeout(window.__budgetBootTimer);render();registerWebMCP();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js?v=1.6.5',{scope:'./'}).catch(()=>{});}catch(error){clearTimeout(window.__budgetBootTimer);app.innerHTML=`<main class="shell">${header('데이터를 열지 못했습니다','기록을 자동으로 초기화하지 않았습니다.')}<section class="card"><p class="error">${esc(error.message)}</p><p class="hint">브라우저 저장소를 지우지 말고 백업 또는 개발자 확인 후 복구해 주세요.</p></section></main>`;}}
document.addEventListener('visibilitychange',async()=>{if(document.visibilityState!=='visible'||!repo.state)return;try{const created=await repo.materializeRecurringExpenses(zonedDate(new Date(),state().settings.timeZone));if(created.length){render();toast(`고정지출 ${created.length}건을 자동 등록했어요.`);}}catch(error){toast(`고정지출 자동 등록 실패: ${error.message}`);}});
boot();
